import gg.jte.convert.jsp.converter.*;
import org.apache.jasper.compiler.JtpConverter;

import java.io.IOException;
import java.io.UncheckedIOException;
import java.net.MalformedURLException;
import java.net.URISyntaxException;
import java.net.URL;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.LinkOption;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.*;
import java.util.function.Consumer;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import java.util.stream.Stream;

public class JspToJteConverter {

    private static final Pattern UNCONVERTED_TAG_REFERENCES = Pattern.compile("<[a-zA-Z0-9\\-]+:[a-zA-Z0-9\\-]+\\b");

    public static void convertFromIntelliJPlugin(String[] commandLineArgs, JspToJteConverter converter, Consumer<Converter> parserSetup) {
        if (commandLineArgs.length < 1) {
            throw new IllegalArgumentException("Missing JSP file, it should be the first argument on the command line.");
        }

        Path jspFile = Paths.get(commandLineArgs[0]);
        jspFile = converter.jspRoot.toAbsolutePath().relativize(jspFile);

        converter.convertTag(jspFile.toString(), parserSetup);
    }

    private final Path jspRoot;
    private final Path jteRoot;
    private final String jteTag;

    public JspToJteConverter(Path jspRoot, Path jteRoot, String jteTag) {
        this.jspRoot = jspRoot;
        this.jteRoot = jteRoot;
        this.jteTag = jteTag;
    }

    public void convertTag(String jspTag, Consumer<Converter> parserSetup) {
        Path jspTagFile = jspRoot.resolve(jspTag);
        String relativeFilePath = jspRoot.relativize(jspTagFile).toString();
        JtpConverter converter = createConverter(relativeFilePath, readFile(jspTagFile), parserSetup);

        String jte = converter.convert();

        System.out.println(jte);

        checkDependencies(jte);

        String jteTemplate = suggestJteFile(jspTag.replace('\\', '/'));
        Path jteTemplateFile = jteRoot.resolve(jteTemplate);
        IoUtils.writeFile(jteTemplateFile, jte);

        replaceUsages(jspTagFile, jteTemplateFile);
    }

    public JspMigrationPlan planTags(Collection<String> jspTags, Consumer<Converter> parserSetup) {
        if (jspTags == null || jspTags.isEmpty()) {
            throw new IllegalArgumentException("At least one JSP tag must be selected.");
        }

        Path normalizedJspRoot = jspRoot.toAbsolutePath().normalize();
        Path normalizedJteRoot = jteRoot.toAbsolutePath().normalize();
        Map<Path, Path> selected = validateSelectedTags(jspTags, normalizedJspRoot);
        Map<Path, Path> destinations = validateDestinations(selected.keySet(), normalizedJteRoot);
        Map<String, Path> selectedInvocations = selectedInvocations(selected);
        Map<Path, JspMigrationPlan.Snapshot> snapshots = snapshotUsageFiles(normalizedJspRoot);
        Map<Path, String> virtualContents = new HashMap<>();
        for (Map.Entry<Path, JspMigrationPlan.Snapshot> snapshot : snapshots.entrySet()) {
            virtualContents.put(snapshot.getKey(), new String(snapshot.getValue().getBytes(), StandardCharsets.UTF_8));
        }

        Map<Path, JtpConverter> converters = new TreeMap<>(Comparator.comparing(Path::toString));
        Map<Path, Set<Path>> dependencies = new TreeMap<>(Comparator.comparing(Path::toString));
        URL resourceBase = getResourceBase();

        for (Map.Entry<Path, Path> entry : selected.entrySet()) {
            Path relativePath = entry.getKey();
            Path absolutePath = entry.getValue();
            JtpConverter converter = createConverter(relativePath.toString(), readFile(absolutePath), parserSetup);
            validateApprovedIncludes(converter.getInlinedIncludes(), resourceBase, normalizedJspRoot);
            JtpConverter.Analysis analysis = converter.analyze();
            Set<Path> tagDependencies = new TreeSet<>(Comparator.comparing(Path::toString));
            List<String> unresolved = new ArrayList<>();
            for (String invocation : analysis.getCustomTags()) {
                Path dependency = selectedInvocations.get(invocation);
                if (dependency != null) {
                    tagDependencies.add(dependency);
                } else if (!converter.getRegisteredTagNames().contains(invocation)) {
                    unresolved.add("<" + invocation);
                }
            }
            if (!unresolved.isEmpty()) {
                checkDependencies(String.join(" ", unresolved));
            }
            for (String includedFile : analysis.getIncludedFiles()) {
                Path include = resolveApprovedInclude(includedFile, resourceBase, normalizedJspRoot);
                snapshots.computeIfAbsent(include, JspToJteConverter::captureSnapshot);
            }
            converters.put(relativePath, converter);
            dependencies.put(relativePath, tagDependencies);
        }

        List<Path> relativeOrder = conversionOrder(dependencies);
        Set<Path> converted = new HashSet<>();
        Map<Path, String> plannedWrites = new TreeMap<>(Comparator.comparing(Path::toString));

        for (Path relativePath : relativeOrder) {
            JtpConverter converter = converters.get(relativePath);
            Path source = selected.get(relativePath);
            String virtualSource = virtualContents.get(source);
            converter.setInput(virtualSource.replace("\r", "").getBytes(StandardCharsets.UTF_8));
            for (Path dependency : dependencies.get(relativePath)) {
                if (!converted.contains(dependency)) {
                    throw new IllegalStateException("Dependency was not converted first: " + dependency);
                }
                String invocation = invocationName(selected.get(dependency));
                String jtePath = normalizedJteRoot.relativize(destinations.get(dependency)).toString().replace('\\', '/');
                converter.register(invocation, new JspJteConverter(jtePath));
            }

            String jte = converter.convert();
            checkDependencies(jte);
            plannedWrites.put(destinations.get(relativePath), jte);
            converted.add(relativePath);

            String oldJspTagPrefix = extractTagPrefix(source);
            String oldJspTagClosing = "</" + oldJspTagPrefix.substring(1) + ">";
            String newJteFile = normalizedJteRoot.relativize(destinations.get(relativePath)).toString().replace('\\', '/');
            for (Map.Entry<Path, String> virtualFile : virtualContents.entrySet()) {
                virtualFile.setValue(replaceUsages(virtualFile.getValue(), oldJspTagPrefix, oldJspTagClosing, newJteFile));
            }
        }

        Set<Path> deletes = new TreeSet<>(Comparator.comparing(Path::toString));
        deletes.addAll(selected.values());
        for (Map.Entry<Path, String> virtualFile : virtualContents.entrySet()) {
            if (!deletes.contains(virtualFile.getKey())) {
                String original = new String(snapshots.get(virtualFile.getKey()).getBytes(), StandardCharsets.UTF_8);
                if (!original.equals(virtualFile.getValue())) {
                    plannedWrites.put(virtualFile.getKey(), virtualFile.getValue());
                }
            }
        }

        List<Path> absoluteOrder = new ArrayList<>();
        for (Path relativePath : relativeOrder) {
            absoluteOrder.add(selected.get(relativePath));
        }
        return new JspMigrationPlan(absoluteOrder, deletes, plannedWrites, snapshots);
    }

    private JtpConverter createConverter(String relativeFilePath, String source, Consumer<Converter> parserSetup) {
        JtpConverter converter = new JtpConverter(
                relativeFilePath,
                source.replace("\r", "").getBytes(StandardCharsets.UTF_8),
                getResourceBase(),
                relativeFilePath.endsWith(".tag"),
                new ConverterOutput()
        );

        converter.register("c:if", new JspIfConverter());
        converter.register("c:forEach", new JspForEachConverter());
        converter.register("c:choose", new JspChooseConverter());
        converter.register("c:when", new JspWhenConverter());
        converter.register("c:otherwise", new JspOtherwiseConverter());
        converter.register("c:set", new JspSetConverter());
        converter.register("fmt:message", new JstlFmtMessageConverter());
        converter.register("fmt:param", new JstlFmtParamConverter());
        converter.register(this.jteTag, new JspJteConverter());

        String[] notConvertedTags = getNotConvertedTags();
        if (notConvertedTags != null) {
            for (String notConvertedTag : notConvertedTags) {
                converter.register(notConvertedTag, new JspNoopConverter());
            }
        }

        if (parserSetup != null) {
            parserSetup.accept(converter);
        }
        return converter;
    }

    private Map<Path, Path> validateSelectedTags(Collection<String> jspTags, Path normalizedJspRoot) {
        Map<Path, Path> selected = new TreeMap<>(Comparator.comparing(Path::toString));
        for (String jspTag : jspTags) {
            if (jspTag == null || jspTag.trim().isEmpty()) {
                throw new IllegalArgumentException("JSP tag paths must not be null or blank.");
            }
            Path supplied = Paths.get(jspTag);
            if (supplied.isAbsolute()) {
                throw new IllegalArgumentException("JSP tag paths must be root-relative: " + jspTag);
            }
            Path relative = supplied.normalize();
            Path absolute = normalizedJspRoot.resolve(relative).normalize();
            if (!absolute.startsWith(normalizedJspRoot)) {
                throw new IllegalArgumentException("JSP tag path is outside the JSP root: " + jspTag);
            }
            if (!relative.toString().replace('\\', '/').endsWith(".tag")) {
                throw new IllegalArgumentException("Selected JSP input is not a .tag file: " + jspTag);
            }
            if (selected.containsKey(relative)) {
                throw new IllegalArgumentException("Duplicate normalized JSP tag path: " + jspTag);
            }
            if (Files.isSymbolicLink(absolute)) {
                throw new IllegalArgumentException("Selected JSP tag must not be a symbolic link: " + jspTag);
            }
            if (!Files.isRegularFile(absolute, LinkOption.NOFOLLOW_LINKS)) {
                throw new IllegalArgumentException("Selected JSP tag is missing or not a regular file: " + jspTag);
            }
            ensureExistingPathBeneathRoot(absolute, normalizedJspRoot, "Selected JSP tag is outside the JSP root: " + jspTag);
            selected.put(relative, absolute);
        }
        return selected;
    }

    private Map<Path, Path> validateDestinations(Set<Path> selected, Path normalizedJteRoot) {
        Map<Path, Path> destinations = new TreeMap<>(Comparator.comparing(Path::toString));
        Set<Path> used = new HashSet<>();
        for (Path relative : selected) {
            String suggested = suggestJteFile(relative.toString().replace('\\', '/'));
            Path destination = normalizedJteRoot.resolve(suggested).normalize();
            if (!destination.startsWith(normalizedJteRoot)) {
                throw new IllegalArgumentException("Generated destination is outside the JTE root: " + destination);
            }
            if (!used.add(destination)) {
                throw new IllegalArgumentException("Generated destinations collide: " + destination);
            }
            if (Files.exists(destination, LinkOption.NOFOLLOW_LINKS)) {
                throw new IllegalArgumentException("Generated destination is already taken: " + destination);
            }
            ensureDestinationBeneathRoot(destination, normalizedJteRoot);
            destinations.put(relative, destination);
        }
        return destinations;
    }

    private Map<String, Path> selectedInvocations(Map<Path, Path> selected) {
        Map<String, Path> result = new HashMap<>();
        for (Map.Entry<Path, Path> entry : selected.entrySet()) {
            String invocation = invocationName(entry.getValue());
            Path previous = result.putIfAbsent(invocation, entry.getKey());
            if (previous != null) {
                throw new IllegalArgumentException("Ambiguous selected invocation name " + invocation + ": " + previous + " and " + entry.getKey());
            }
        }
        return result;
    }

    private Map<Path, JspMigrationPlan.Snapshot> snapshotUsageFiles(Path normalizedJspRoot) {
        Map<Path, JspMigrationPlan.Snapshot> result = new TreeMap<>(Comparator.comparing(Path::toString));
        try (Stream<Path> stream = Files.walk(normalizedJspRoot)) {
            stream.filter(path -> Files.isRegularFile(path, LinkOption.NOFOLLOW_LINKS))
                    .map(path -> path.toAbsolutePath().normalize())
                    .filter(JspToJteConverter::isUsageFile)
                    .sorted(Comparator.comparing(Path::toString))
                    .forEach(path -> result.put(path, captureSnapshot(path)));
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
        return result;
    }

    private static boolean isUsageFile(Path path) {
        String fileName = path.toString();
        return fileName.endsWith(".jsp") || fileName.endsWith(".jsp.inc") || fileName.endsWith(".tag");
    }

    private static JspMigrationPlan.Snapshot captureSnapshot(Path path) {
        try {
            return JspMigrationPlan.Snapshot.capture(path);
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }

    private void validateApprovedIncludes(Set<String> includes, URL resourceBase, Path normalizedJspRoot) {
        for (String include : includes) {
            resolveApprovedInclude(include, resourceBase, normalizedJspRoot);
        }
    }

    private Path resolveApprovedInclude(String include, URL resourceBase, Path normalizedJspRoot) {
        if (include == null || include.trim().isEmpty()) {
            throw new IllegalArgumentException("Approved include paths must not be null or blank.");
        }
        try {
            Path base = Paths.get(resourceBase.toURI()).toAbsolutePath().normalize();
            String relativeInclude = include.startsWith("/") ? include.substring(1) : include;
            Path resolved = base.resolve(relativeInclude).normalize().toAbsolutePath();
            if (!resolved.startsWith(normalizedJspRoot)) {
                throw new IllegalArgumentException("Approved include is outside the JSP root: " + include);
            }
            if (Files.exists(resolved, LinkOption.NOFOLLOW_LINKS)) {
                ensureExistingPathBeneathRoot(resolved, normalizedJspRoot, "Approved include is outside the JSP root: " + include);
            }
            return resolved;
        } catch (URISyntaxException | IllegalArgumentException e) {
            if (e instanceof IllegalArgumentException) {
                throw (IllegalArgumentException) e;
            }
            throw new IllegalArgumentException("Unsupported resource base for approved include: " + resourceBase, e);
        }
    }

    private static void ensureExistingPathBeneathRoot(Path path, Path root, String message) {
        try {
            Path realRoot = root.toRealPath();
            if (!path.toRealPath().startsWith(realRoot)) {
                throw new IllegalArgumentException(message);
            }
        } catch (IOException e) {
            throw new IllegalArgumentException(message, e);
        }
    }

    private static void ensureDestinationBeneathRoot(Path destination, Path root) {
        Path existing = destination.getParent();
        while (existing != null && !Files.exists(existing, LinkOption.NOFOLLOW_LINKS)) {
            existing = existing.getParent();
        }
        if (existing == null || !Files.exists(root, LinkOption.NOFOLLOW_LINKS)) {
            return;
        }
        try {
            if (!existing.toRealPath().startsWith(root.toRealPath())) {
                throw new IllegalArgumentException("Generated destination is outside the JTE root: " + destination);
            }
        } catch (IOException e) {
            throw new IllegalArgumentException("Could not validate generated destination: " + destination, e);
        }
    }

    private List<Path> conversionOrder(Map<Path, Set<Path>> dependencies) {
        List<Path> result = new ArrayList<>();
        Set<Path> remaining = new TreeSet<>(Comparator.comparing(Path::toString));
        remaining.addAll(dependencies.keySet());
        while (!remaining.isEmpty()) {
            Path next = null;
            for (Path candidate : remaining) {
                if (result.containsAll(dependencies.get(candidate))) {
                    next = candidate;
                    break;
                }
            }
            if (next == null) {
                List<Path> cycle = findCycle(remaining.iterator().next(), dependencies, remaining, new ArrayList<>(), new HashSet<>());
                throw new IllegalArgumentException("Cyclic JSP tag dependency: " + joinCycle(cycle));
            }
            result.add(next);
            remaining.remove(next);
        }
        return result;
    }

    private List<Path> findCycle(Path current, Map<Path, Set<Path>> dependencies, Set<Path> remaining, List<Path> path, Set<Path> visiting) {
        int existing = path.indexOf(current);
        if (existing >= 0) {
            List<Path> cycle = new ArrayList<>(path.subList(existing, path.size()));
            cycle.add(current);
            return cycle;
        }
        if (!visiting.add(current)) {
            return Collections.emptyList();
        }
        path.add(current);
        for (Path dependency : dependencies.get(current)) {
            if (remaining.contains(dependency)) {
                List<Path> cycle = findCycle(dependency, dependencies, remaining, path, visiting);
                if (!cycle.isEmpty()) {
                    return cycle;
                }
            }
        }
        path.remove(path.size() - 1);
        return Collections.emptyList();
    }

    private static String joinCycle(List<Path> cycle) {
        List<String> paths = new ArrayList<>();
        for (Path path : cycle) {
            paths.add(path.toString().replace('\\', '/'));
        }
        return String.join(" -> ", paths);
    }

    @SuppressWarnings("unused")
    public void replaceUsages(String jspTag, String jteTag) {
        replaceUsages(jspRoot.resolve(jspTag), jteRoot.resolve(jteTag));
    }

    public void replaceUsages(Path jspTag, Path jteTag) {
        String oldJspTagPrefix = extractTagPrefix(jspTag);
        String oldJspTagClosing = "</" + oldJspTagPrefix.substring(1) + ">";
        String newJteFile = jteRoot.relativize(jteTag).toString().replace('\\', '/');

        IoUtils.deleteFile(jspTag);

        try (Stream<Path> stream = Files.walk(jspRoot)) {
            stream.filter(Files::isRegularFile)
                    .filter(path -> !Files.isDirectory(path))
                    .filter(JspToJteConverter::isUsageFile)
                    .forEach(jspFile -> replaceUsages(jspFile, oldJspTagPrefix, oldJspTagClosing, newJteFile));
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }

    protected String readFile(Path jspTag) {
        return IoUtils.readFile(jspTag);
    }

    private void replaceUsages(Path jspFile, String oldJspTagPrefix, String oldJspTagClosing, String newJteFile) {
        String original = IoUtils.readFile(jspFile);
        String replaced = replaceUsages(original, oldJspTagPrefix, oldJspTagClosing, newJteFile);
        if (!original.equals(replaced)) {
            IoUtils.writeFile(jspFile, replaced);
        }
    }

    private String replaceUsages(String content, String oldJspTagPrefix, String oldJspTagClosing, String newJteFile) {
        StringBuilder jspContent = new StringBuilder(content);
        int lastIndex = 0;
        while ((lastIndex = jspContent.indexOf(oldJspTagPrefix, lastIndex)) >= 0) {
            int boundaryIndex = lastIndex + oldJspTagPrefix.length();
            if (boundaryIndex < jspContent.length()) {
                char character = jspContent.charAt(boundaryIndex);
                if (Character.isWhitespace(character) || character == '/' || character == '>') {
                    String replacement = "<" + jteTag + " jte=\"" + newJteFile + "\"";
                    jspContent.replace(lastIndex, boundaryIndex, replacement);
                    lastIndex += replacement.length();
                    continue;
                }
            }
            lastIndex++;
        }

        lastIndex = 0;
        String newClosing = "</" + jteTag + ">";
        while ((lastIndex = jspContent.indexOf(oldJspTagClosing, lastIndex)) >= 0) {
            jspContent.replace(lastIndex, lastIndex + oldJspTagClosing.length(), newClosing);
            lastIndex += newClosing.length();
        }
        return jspContent.toString();
    }

    private String extractTagPrefix(Path jspTag) {
        return "<" + invocationName(jspTag);
    }

    private String invocationName(Path jspTag) {
        String fileName = jspTag.getFileName().toString();
        String tagName = fileName.substring(0, fileName.indexOf('.'));
        String namespace = jspTag.getParent().getFileName().toString();
        if ("tags".equals(namespace)) {
            namespace = "include";
        }
        return namespace + ":" + tagName;
    }

    protected URL getResourceBase() {
        try {
            return Paths.get("").toUri().toURL();
        } catch (MalformedURLException e) {
            throw new UncheckedIOException(e);
        }
    }

    public String suggestJteFile(String jspFile) {
        int fileSeparatorIndex = jspFile.indexOf('.');
        if (fileSeparatorIndex == -1) {
            throw new IllegalArgumentException("JSP file without file extension " + jspFile);
        }

        String jspFileWithoutExtension = jspFile.substring(0, fileSeparatorIndex);
        StringBuilder jteFile = new StringBuilder();
        jteFile.append(jspFileWithoutExtension);
        CamelCaseConverter.convertTo(jteFile);
        jteFile.append(".jte");
        return jteFile.toString();
    }

    protected void checkDependencies(String jteCode) {
        List<String> unresolvedJspTags = findUnresolvedJspTags(jteCode);
        if (unresolvedJspTags.isEmpty()) {
            return;
        }

        Set<String> notConvertedTagsSet = getNotConvertedTagsAsSet();
        Set<String> errors = new LinkedHashSet<>();
        for (String unresolvedJspTag : unresolvedJspTags) {
            if (!notConvertedTagsSet.contains(unresolvedJspTag)) {
                errors.add("The tag " + unresolvedJspTag + "/> is used by this tag and not converted to jte yet. You should convert " + unresolvedJspTag + "/> first. If this is a tag that should be always converted by hand, implement getNotConvertedTags() and add it there.");
            }
        }

        if (!errors.isEmpty()) {
            throw new UnsupportedOperationException(String.join("\n", errors));
        }
    }

    private Set<String> getNotConvertedTagsAsSet() {
        String[] notConvertedTags = getNotConvertedTags();
        Set<String> notConvertedTagsSet = new HashSet<>();
        if (notConvertedTags != null) {
            for (String notConvertedTag : notConvertedTags) {
                notConvertedTagsSet.add("<" + notConvertedTag);
            }
        }
        return notConvertedTagsSet;
    }

    protected List<String> findUnresolvedJspTags(String jteCode) {
        List<String> result = new ArrayList<>();
        Matcher matcher = UNCONVERTED_TAG_REFERENCES.matcher(jteCode);
        while (matcher.find()) {
            result.add(matcher.group());
        }
        return result;
    }

    protected String[] getNotConvertedTags() {
        return null;
    }
}
